def mergesort(items):
    comps = [0]

    def merge(left, right):
        i = j = 0
        out = []
        while i < len(left) and j < len(right):
            comps[0] += 1
            if left[i][0] <= right[j][0]:
                out.append(left[i])
                i += 1
            else:
                out.append(right[j])
                j += 1
        out.extend(left[i:])
        out.extend(right[j:])
        return out

    def sort(seq):
        if len(seq) <= 1:
            return list(seq)
        mid = len(seq) // 2
        return merge(sort(seq[:mid]), sort(seq[mid:]))

    result = sort(items)
    return comps[0], result


count, result = mergesort([(3, "a"), (1, "b"), (3, "c"), (2, "d")])
assert count == 5
assert [label for _, label in result] == ["b", "d", "a", "c"]
assert 6 + 9 - 1 == 14
print(count, "".join(label for _, label in result))
